head.script:
// 테스트 설명, 유효성 값 설정
//  ★ _3 분리본 : mergeInfo.colIndex 가 숨겨진 Column 의 Body Cell 도 포함하여 인덱스가 설정됨을 검증.
//     _1 의 공통 validation 은 중복 생성하지 않는다.
scwin.tData = {
    "description" : "[gridView > M > mergeCell]<br/>Body Cell 정보를 사용하여 Body 영역의 특정 Cell 을 병합합니다.",
    "validation" : [
        "mergeInfo.colIndex 는 숨겨진 Column 의 Body Cell 도 포함하여 인덱스가 설정됩니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (그리드 생성 + 중간 Column(colIndex 1) 숨김)
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 데이터 — 모든 Cell 값이 서로 다름(R{행}C{컬럼}). 숨김 Column 포함 인덱스 추적을 위해
//          데이터 col index(0~3) 와 표시값 C0~C3 을 일치시킨다.
scwin.MERGE_DATA = [
    { "col1": "R0C0", "col2": "R0C1", "col3": "R0C2", "col4": "R0C3" },
    { "col1": "R1C0", "col2": "R1C1", "col3": "R1C2", "col4": "R1C3" },
    { "col1": "R2C0", "col2": "R2C1", "col3": "R2C2", "col4": "R2C3" },
    { "col1": "R3C0", "col2": "R3C1", "col3": "R3C2", "col4": "R3C3" },
    { "col1": "R4C0", "col2": "R4C1", "col3": "R4C2", "col4": "R4C3" }
];



// comp 생성 : 단일 그리드 1개를 동적 생성한 뒤, 중간 Column(데이터 colIndex 1) 을 숨김 처리한다.
//  → 화면에는 col0 / col2 / col3 만 보이며, 화면상 2번째 보이는 Column 의 데이터 인덱스는 2 가 된다.
scwin.comp_init = async function () {
    // 기존 target / label / DataList 정리
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove(dlt_bind.id);
    }
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="5행 4열 그리드. 데이터 colIndex 1(C1) Column 을 setColumnVisible(1,false) 로 숨김 → 화면에는 C0 / C2 / C3 만 표시됨. colIndex 는 숨김 Column 도 포함하여 카운트되므로, 화면상 2번째 보이는 Column 의 데이터 인덱스는 2 임"', '', 'label1');

    // DataList 생성 후 검증용 데이터 적재
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');
    dlt_bind.setJSON(scwin.MERGE_DATA, false);

    let cList = $c.gcm.createCList({ dataList: "data:" + dlt_bind.id });

    let grp_comp = document.querySelector('.tc_group_basic');
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' checkAllType="false" defaultCellHeight="38" id="" style="width:520px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="mergeCell sample"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column1" value="col0"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column2" value="col1"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="column3" value="col2"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="column4" value="col3"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col1" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col2" value=""></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="col3" value=""></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="col4" value=""></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate("target1", "gridView", strTarget, grp_comp);

    // 중간 Column(데이터 colIndex 1) 숨김 처리 — colIndex 가 숨김 Column 도 포함하여 카운트하는지 검증하기 위함
    target1.setColumnVisible(1, false);
}



// 공통 : 병합 시작(anchor) td 의 rowSpan/colSpan 과 표시값을 반환
//  - td id 형식 : target1_cell_{row}_{col} (col 은 데이터 colIndex, 숨김 Column 포함)
scwin.getAnchorSpan = function (rowIndex, colIndex) {
    let td = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!td) return null;
    return { rowSpan: td.rowSpan || 1, colSpan: td.colSpan || 1, text: (td.textContent || '').trim() };
}



// 숨김 Column 인덱스 검증 (버튼 1개) :
//  데이터 colIndex 1(C1) 은 setColumnVisible(1,false) 로 숨김 → 화면에는 C0 / C2 / C3 만 표시됨.
//  mergeCell({rowIndex:0, colIndex:2, rowSpan:2}) 호출 시 colIndex=2 는 숨김 Column(인덱스1)도 포함하여 카운트하므로
//  화면상 2번째로 보이는 Column(데이터 index2, 표시값 R0C2)에 세로 병합이 적용된다.
//  → 숨겨진 Column 의 Body Cell 도 인덱스에 포함됨이 입증된다.
scwin.btn_verify_onclick = function (e) {
    let bottom = wf_body_bottom.getObj("scwin");
    bottom.btn_clear_onclick();

    // colIndex=2 : 숨김 Column(인덱스1) 을 포함하여 카운트 → 화면상 2번째 보이는 Column(C2)
    target1.mergeCell({ "rowIndex": 0, "colIndex": 2, "rowSpan": 2 });

    // 병합 시작 Cell(anchor) 조회 — td id 는 데이터 colIndex(숨김 포함) 기준
    let anchor = scwin.getAnchorSpan(0, 2);
    let applied = !!(anchor && anchor.text.indexOf("C2") >= 0 && anchor.rowSpan === 2);
    bottom.setReturnValue("colIndex 2(숨겨진 Column 포함하여 카운트) → 화면 2번째 Column 에 병합 적용 : " + applied + " (표시값='" + (anchor ? anchor.text : "") + "')");
}
